/** The developers' patch notes, by year, and which game version was live when. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { heading, sections, table, titleCase } from '../render.mjs'

/**
 * Make a note written for a chat channel safe to sit on a page with other notes.
 *
 * Its own headings would break up the page outline, so they become bold lines. Mentions
 * are ids that only resolve in the channel. And a note that opens a code fence without
 * closing it would swallow every note after it.
 */
function noteBody(body) {
  const text = body
    .replace(/<@[&!]?\d+>|<#\d+>/g, '')
    .replace(/<a?(:\w+:)\d+>/g, '$1')
    .split('\n')
    .map(line => {
      const title = /^#{1,6}\s+(.*)$/.exec(line)
      if (!title) return line.trimEnd()
      const words = title[1].replace(/\*\*/g, '').trim()
      return words ? `**${words}**` : ''
    })
    .join('\n')
    .replace(/\*\*([^*\n]*?)\s+\*\*/g, '**$1**')
  const fences = (text.match(/^```/gm) ?? []).length
  return fences % 2 === 0 ? text : `${text}\n\`\`\``
}

export function build(context) {
  const { knowledge } = context.sdk
  const notes = knowledge.PATCH_NOTES
  const years = [...new Set(notes.map(note => note.postedAt.slice(0, 4)))].sort().reverse()
  const yearTitle = year => `Game Patch Notes ${year}`

  for (const year of years) {
    const inYear = notes.filter(note => note.postedAt.startsWith(year)).sort((a, b) => b.postedAt.localeCompare(a.postedAt))
    context.page(
      yearTitle(year),
      sections(
        ...inYear.map(note =>
          sections(
            heading(2, `${note.postedAt.slice(0, 10)}${note.version ? ` · ${note.version}` : ''} · ${titleCase(note.kind)}`),
            noteBody(note.body),
          ),
        ),
        `Back to ${context.link('Game Patch Notes')}.`,
      ),
      { source: 'PATCH_NOTES', entry: '@beardedunicorn/thetowersdk/knowledge' },
    )
  }

  context.page(
    'Game Patch Notes',
    sections(
      context.overview('patch-notes'),
      `${notes.length} notes, from ${notes.map(note => note.postedAt).sort()[0].slice(0, 10)} to ${notes.map(note => note.postedAt).sort().at(-1).slice(0, 10)}.`,
      table(
        ['Year', 'Notes', 'Versions'],
        years.map(year => {
          const inYear = notes.filter(note => note.postedAt.startsWith(year))
          const versions = [...new Set(inYear.map(note => note.version).filter(Boolean))]
          return [context.link(yearTitle(year), year), inYear.length, versions.length > 0 ? `${versions.at(0)} to ${versions.at(-1)}` : '']
        }),
      ),
      `See also ${context.link('Game Version History')}.`,
    ),
    { source: 'PATCH_NOTES', entry: '@beardedunicorn/thetowersdk/knowledge' },
  )

  context.page(
    'Game Version History',
    sections(
      `The pages of this wiki describe **${context.gameVersion}**.`,
      table(
        ['Version', 'From', 'Until', 'Basis'],
        knowledge.GAME_VERSION_TIMELINE.map(window => [window.version, window.from, window.until ?? 'now', window.basis]),
      ),
      `Back to ${context.link('Game Patch Notes')}.`,
    ),
    { source: 'GAME_VERSION_TIMELINE', entry: '@beardedunicorn/thetowersdk/knowledge' },
  )

  context.group('History', ['Game Patch Notes', 'Game Version History'])
}
